#include <iostream>

int main() {
    unsigned u = 11;  // Initialize to one greater than the first value to print (10)
    while (u > 0) {
        --u;  // Decrement first to avoid off-by-one errors
        std::cout << "Value: " << u << std::endl;  // Process the value
    }
    // Loop will print 10 down to 0, then exit safely
    return 0;
}
